        default_secret = alicloud.kms.Secret("default",
            secret_data=name,
            secret_name=name,
            version_id="v1",
            dkms_instance_id=default_key.dkms_instance_id,
            encryption_key_id=default_key.id,
            force_delete_without_recovery=True)
        default_secret2 = alicloud.apig.Secret("default",
            gateway_type="API",
            name=name,
            secret_source="KMS",
            secret_data=default_secret.secret_data,
            kms_config={
                "kms_instance_id": default_secret.dkms_instance_id,
                "kms_key_id": default_secret.encryption_key_id,
            })
